function chooseGcd(choice,button){if(gAnswered)return;gAnswered=true;const x=gcdQuestions[gIndex],ok=choice===x.c;if(ok)gScore++;document.querySelector('#score4').textContent=gScore;[...document.querySelectorAll('#answers4 button')].forEach((b,i)=>{b.disabled=true;if(i===x.c)b.classList.add('correct-answer')});if(!ok)button.classList.add('wrong-answer');const f=document.querySelector('#feedback4');f.textContent=(ok?dict().correct:dict().wrong)+' '+x.e[lang()];f.className=ok?'correct':'wrong';const n=document.querySelector('#next4');n.textContent=gIndex===9?dict().finish:dict().next;n.hidden=false}
function nextGcd(){if(gIndex<9){gIndex++;renderGcd()}else{document.querySelector('#question-card4').hidden=true;document.querySelector('#result4').hidden=false;document.querySelector('#result-title4').textContent=dict().resultTitle;document.querySelector('#result-text4').textContent=gScore+'/10 — '+(gScore>=8?dict().resultGood:gScore>=5?dict().resultMid:dict().resultLow);document.querySelector('#restart4').textContent=dict().restart}}
function restartGcd(){gIndex=0;gScore=0;document.querySelector('#score4').textContent='0';document.querySelector('#result4').hidden=true;document.querySelector('#question-card4').hidden=false;renderGcd()}
