function makeQuizState(items,n){return{items,n,index:0,score:0,answered:false}}
const sieveState=makeQuizState(sieveQuestions,6),euclidState=makeQuizState(euclidQuestions,7),setsState=makeQuizState(setsQuestions,8);
function renderExtra(state){const x=state.items[state.index],n=state.n;document.querySelector('#question-number'+n).textContent=(state.index+1)+' / 10';document.querySelector('#level'+n).textContent=dict().level[x.l];document.querySelector('#question'+n).textContent=x.q[lang()];const box=document.querySelector('#answers'+n);box.innerHTML='';x.a.forEach((answer,i)=>{const b=document.createElement('button');b.textContent=Array.isArray(answer)?answer[lang()]:answer;b.addEventListener('click',()=>chooseExtra(state,i,b));box.appendChild(b)});document.querySelector('#feedback'+n).textContent='';document.querySelector('#feedback'+n).className='';document.querySelector('#next'+n).hidden=true;state.answered=false}
function chooseExtra(state,choice,button){if(state.answered)return;state.answered=true;const x=state.items[state.index],ok=choice===x.c,n=state.n;if(ok)state.score++;document.querySelector('#score'+n).textContent=state.score;[...document.querySelectorAll('#answers'+n+' button')].forEach((b,i)=>{b.disabled=true;if(i===x.c)b.classList.add('correct-answer')});if(!ok)button.classList.add('wrong-answer');const f=document.querySelector('#feedback'+n);f.textContent=(ok?dict().correct:dict().wrong)+' '+x.e[lang()];f.className=ok?'correct':'wrong';const next=document.querySelector('#next'+n);next.textContent=state.index===9?dict().finish:dict().next;next.hidden=false}
function nextExtra(state){const n=state.n;if(state.index<9){state.index++;renderExtra(state)}else{document.querySelector('#question-card'+n).hidden=true;document.querySelector('#result'+n).hidden=false;document.querySelector('#result-title'+n).textContent=dict().resultTitle;document.querySelector('#result-text'+n).textContent=state.score+'/10 — '+(state.score>=8?dict().resultGood:state.score>=5?dict().resultMid:dict().resultLow);document.querySelector('#restart'+n).textContent=dict().restart}}
function restartExtra(state){const n=state.n;state.index=0;state.score=0;document.querySelector('#score'+n).textContent='0';document.querySelector('#result'+n).hidden=true;document.querySelector('#question-card'+n).hidden=false;renderExtra(state)}
function renderSieve(){renderExtra(sieveState)}function renderEuclid(){renderExtra(euclidState)}function renderSets(){renderExtra(setsState)}
function updateCorrectedLabels(){document.querySelector('[data-i18n7="sieveLabel"]').textContent=script==='latn'?'LEKCIJA 3':'ЛЕКЦИЈА 3'}
document.querySelectorAll('[data-script]').forEach(b=>b.addEventListener('click',()=>setTimeout(updateCorrectedLabels,0)));setTimeout(updateCorrectedLabels,0);
